#!/usr/bin/env python3
"""Vaxcrate dispatch cadence analysis.

Reads campaign + pricing inputs, computes annual margins under 6-day vs 12-day
dispatch models, and writes:
- /root/vaxcrate_analysis.json
- /root/vaxcrate_summary.md

This file is intentionally self-contained and uses only the Python stdlib.
"""

from __future__ import annotations

import csv
import json
from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Tuple


ROOT = Path("/root")

MANIFEST_PATH = ROOT / "campaign_manifest.json"
CRATE_COST_PATH = ROOT / "crate_cost.csv"
BILLING_PATH = ROOT / "billing.csv"
LOCATION_OVERRIDES_PATH = ROOT / "location_overrides.csv"
SUSPENSIONS_PATH = ROOT / "suspensions.csv"

OUT_JSON_PATH = ROOT / "vaxcrate_analysis.json"
OUT_MD_PATH = ROOT / "vaxcrate_summary.md"

THRESHOLD_USD = Decimal("11000")


def load_csv_dicts(path: Path) -> List[Dict[str, str]]:
    with path.open("r", newline="") as f:
        return list(csv.DictReader(f))


def d(val: Any) -> Decimal:
    """Parse numbers robustly into Decimal."""
    # Manifest numeric fields might already be int/float.
    return Decimal(str(val).strip())


def money(val: Decimal) -> float:
    """Round a Decimal monetary value to cents and return as float."""
    q = val.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return float(q)


@dataclass(frozen=True)
class DispatchModel:
    key: str
    days_per_dispatch: int
    dispatches_per_year: int


MODEL_6 = DispatchModel(key="6_day", days_per_dispatch=6, dispatches_per_year=60)
MODEL_12 = DispatchModel(key="12_day", days_per_dispatch=12, dispatches_per_year=30)


def flatten_manifest_campaigns(manifest_obj: Any) -> List[Dict[str, Any]]:
    """Return a list of campaign objects from the manifest input."""
    if isinstance(manifest_obj, list):
        # Already a flat list of campaigns.
        return manifest_obj

    if isinstance(manifest_obj, dict):
        if "campaigns" in manifest_obj and isinstance(manifest_obj["campaigns"], list):
            return manifest_obj["campaigns"]

        # Observed structure in this task: {"regions": [{"campaigns": [...]}, ...]}
        regions = manifest_obj.get("regions")
        if isinstance(regions, list):
            out: List[Dict[str, Any]] = []
            for r in regions:
                if not isinstance(r, dict):
                    continue
                cs = r.get("campaigns")
                if isinstance(cs, list):
                    out.extend([c for c in cs if isinstance(c, dict)])
            return out

    raise ValueError("Unsupported campaign manifest structure")


def collect_hold_campaign_ids(susp_rows: List[Dict[str, str]]) -> set[str]:
    hold_ids: set[str] = set()
    for row in susp_rows:
        cid = (row.get("campaign_id") or "").strip()
        status = (row.get("suspension_status") or "").strip().lower()
        if cid and status == "hold":
            hold_ids.add(cid)
    return hold_ids


def resolve_payment_for_campaign(
    campaign: Dict[str, Any],
    billing_rows: List[Dict[str, str]],
) -> Decimal:
    labels: List[str] = []

    name = campaign.get("campaign_name")
    if isinstance(name, str) and name.strip():
        labels.append(name.strip())

    aliases = campaign.get("alias_labels")
    if isinstance(aliases, list):
        for a in aliases:
            if isinstance(a, str) and a.strip():
                labels.append(a.strip())

    label_set = set(labels)
    if not label_set:
        raise ValueError(f"Campaign {campaign.get('campaign_id')} has no labels to match billing")

    active_matches: List[Dict[str, str]] = []
    for row in billing_rows:
        row_label = (row.get("campaign_label") or "").strip()
        if row_label not in label_set:
            continue
        if (row.get("status") or "").strip().lower() != "active":
            continue
        active_matches.append(row)

    if not active_matches:
        raise ValueError(
            f"No active billing rows found for campaign_id={campaign.get('campaign_id')} labels={sorted(label_set)}"
        )

    # Latest = lexicographically greatest cycle_tag.
    best = max(active_matches, key=lambda r: (r.get("cycle_tag") or ""))
    p = (best.get("payment_per_dispatch_per_clinic_usd") or "").strip()
    if not p:
        raise ValueError(
            f"Billing row missing payment_per_dispatch_per_clinic_usd for campaign_id={campaign.get('campaign_id')}"
        )
    return d(p)


def resolve_active_clinics_for_campaign(
    campaign: Dict[str, Any],
    override_rows: List[Dict[str, str]],
) -> int:
    cid = (campaign.get("campaign_id") or "").strip()
    if not cid:
        raise ValueError("Manifest campaign missing campaign_id")

    best_rev: Optional[int] = None
    best_active: Optional[int] = None

    for row in override_rows:
        if (row.get("campaign_id") or "").strip() != cid:
            continue

        if (row.get("state") or "").strip().lower() != "approved":
            continue

        rev_raw = (row.get("revision") or "").strip()
        active_raw = (row.get("active_clinics") or "").strip()
        if not rev_raw or not active_raw:
            # Explicitly skip blank revision or blank active_clinics.
            continue

        try:
            rev = int(float(rev_raw))
        except ValueError:
            continue

        try:
            active = int(float(active_raw))
        except ValueError:
            continue

        if best_rev is None or rev > best_rev:
            best_rev = rev
            best_active = active

    if best_active is not None:
        return best_active

    default_active = campaign.get("default_active_clinics")
    if default_active is None or str(default_active).strip() == "":
        raise ValueError(f"No active clinics override and default_active_clinics missing for {cid}")
    return int(float(default_active))


def load_crate_costs(crate_rows: List[Dict[str, str]]) -> Dict[str, Decimal]:
    out: Dict[str, Decimal] = {}
    for row in crate_rows:
        tier = (row.get("crate_tier") or "").strip()
        cost = (row.get("crate_cost_usd") or "").strip()
        if not tier or not cost:
            continue
        out[tier] = d(cost)
    return out


def compute_campaign_metrics(
    *,
    campaign: Dict[str, Any],
    payment_per_dispatch_per_clinic_usd: Decimal,
    active_clinics: int,
    crate_cost_usd: Decimal,
) -> Dict[str, Any]:
    drug_cost_per_1000 = d(campaign.get("drug_cost_per_1000_doses_usd"))
    doses_per_day = d(campaign.get("doses_per_day"))

    def annual_revenue(model: DispatchModel) -> Decimal:
        return payment_per_dispatch_per_clinic_usd * d(active_clinics) * d(model.dispatches_per_year)

    def annual_drug_cost(model: DispatchModel) -> Decimal:
        return (
            drug_cost_per_1000
            * d(active_clinics)
            * doses_per_day
            * d(model.days_per_dispatch)
            * d(model.dispatches_per_year)
            / Decimal("1000")
        )

    def annual_crate_cost(model: DispatchModel) -> Decimal:
        # crate_cost_usd is per-dispatch; annualize by dispatches per year.
        return crate_cost_usd * d(model.dispatches_per_year)

    rev6 = annual_revenue(MODEL_6)
    rev12 = annual_revenue(MODEL_12)

    drug6 = annual_drug_cost(MODEL_6)
    drug12 = annual_drug_cost(MODEL_12)

    crate6 = annual_crate_cost(MODEL_6)
    crate12 = annual_crate_cost(MODEL_12)

    margin6 = rev6 - drug6 - crate6
    margin12 = rev12 - drug12 - crate12
    diff = margin12 - margin6

    return {
        "campaign_id": (campaign.get("campaign_id") or "").strip(),
        "campaign_name": (campaign.get("campaign_name") or "").strip(),
        "active_clinics": int(active_clinics),
        "crate_tier": (campaign.get("crate_tier") or "").strip(),
        "payment_per_dispatch_per_clinic_usd": money(payment_per_dispatch_per_clinic_usd),
        "crate_cost_usd": money(crate_cost_usd),
        "annual_revenue_6_day_usd": money(rev6),
        "annual_revenue_12_day_usd": money(rev12),
        "annual_drug_cost_6_day_usd": money(drug6),
        "annual_drug_cost_12_day_usd": money(drug12),
        "annual_crate_cost_6_day_usd": money(crate6),
        "annual_crate_cost_12_day_usd": money(crate12),
        "annual_margin_6_day_usd": money(margin6),
        "annual_margin_12_day_usd": money(margin12),
        "annual_margin_difference_12_minus_6_usd": money(diff),
    }


def main() -> None:
    # 1) Load inputs.
    manifest_obj = json.loads(MANIFEST_PATH.read_text())
    manifest_campaigns = flatten_manifest_campaigns(manifest_obj)

    crate_rows = load_csv_dicts(CRATE_COST_PATH)
    billing_rows = load_csv_dicts(BILLING_PATH)
    override_rows = load_csv_dicts(LOCATION_OVERRIDES_PATH)
    susp_rows = load_csv_dicts(SUSPENSIONS_PATH)

    # 2) Filter campaigns.
    hold_ids = collect_hold_campaign_ids(susp_rows)

    retained: List[Dict[str, Any]] = []
    for c in manifest_campaigns:
        if (c.get("analysis_flag") or "").strip() != "review":
            continue
        cid = (c.get("campaign_id") or "").strip()
        if cid in hold_ids:
            continue
        retained.append(c)

    if not retained:
        raise ValueError("No campaigns retained after filtering")

    # 5) Look up crate cost.
    crate_cost_by_tier = load_crate_costs(crate_rows)

    per_campaign: List[Dict[str, Any]] = []

    for c in retained:
        cid = (c.get("campaign_id") or "").strip()

        # 3) Resolve billing rows.
        payment = resolve_payment_for_campaign(c, billing_rows)

        # 4) Resolve active clinics from overrides.
        active_clinics = resolve_active_clinics_for_campaign(c, override_rows)

        # 5) Look up crate cost.
        tier = (c.get("crate_tier") or "").strip()
        if tier not in crate_cost_by_tier:
            raise ValueError(f"No crate_cost_usd found for crate_tier={tier} (campaign_id={cid})")
        crate_cost_usd = crate_cost_by_tier[tier]

        per_campaign.append(
            compute_campaign_metrics(
                campaign=c,
                payment_per_dispatch_per_clinic_usd=payment,
                active_clinics=active_clinics,
                crate_cost_usd=crate_cost_usd,
            )
        )

    # Sort campaigns by campaign_id ascending.
    per_campaign.sort(key=lambda x: x["campaign_id"])

    # 7) Totals.
    total6 = sum(d(c["annual_margin_6_day_usd"]) for c in per_campaign)
    total12 = sum(d(c["annual_margin_12_day_usd"]) for c in per_campaign)
    total_diff = total12 - total6
    abs_total_diff = abs(total_diff)

    # 8) Decision.
    decision = "move_to_12_day" if abs_total_diff < THRESHOLD_USD else "keep_6_day"
    justification = (
        f"Absolute total margin difference is ${money(abs_total_diff):,.2f}; "
        f"threshold is ${money(THRESHOLD_USD):,.2f}, so decision is '{decision}'."
    )

    # 9) Build JSON output.
    out = {
        "assumptions": {
            "models": {
                "6_day": {
                    "days_per_dispatch": MODEL_6.days_per_dispatch,
                    "dispatches_per_year": MODEL_6.dispatches_per_year,
                },
                "12_day": {
                    "days_per_dispatch": MODEL_12.days_per_dispatch,
                    "dispatches_per_year": MODEL_12.dispatches_per_year,
                },
            },
            "annual_crate_cost_interpretation": "crate_cost_usd is per dispatch; annual_crate_cost_usd = crate_cost_usd * dispatches_per_year",
            "decision_threshold_absolute_total_margin_difference_usd": money(THRESHOLD_USD),
        },
        "campaigns": per_campaign,
        "totals": {
            "total_annual_margin_6_day_usd": money(total6),
            "total_annual_margin_12_day_usd": money(total12),
            "total_annual_margin_difference_12_minus_6_usd": money(total_diff),
            "absolute_total_margin_difference_usd": money(abs_total_diff),
        },
        "recommendation": {
            "decision": decision,
            "absolute_difference_usd": money(abs_total_diff),
            "threshold_usd": money(THRESHOLD_USD),
            "justification": justification,
        },
    }

    OUT_JSON_PATH.write_text(json.dumps(out, indent=2) + "\n")

    # 10) Build markdown summary (4–8 non-empty lines).
    md_lines = [
        f"Total 6-day annual margin (USD): ${money(total6):,.2f}",
        f"Total 12-day annual margin (USD): ${money(total12):,.2f}",
        f"Absolute difference (USD): ${money(abs_total_diff):,.2f}",
        f"Decision: {decision}",
    ]
    OUT_MD_PATH.write_text("\n".join(md_lines) + "\n")


if __name__ == "__main__":
    main()

